75	void unfoldURI(std::vector<std::string>& result,
76	               const std::vector<std::string>& args)
77	{
78	  for (const auto& i : args) {
79	    paramed_string::expand(std::begin(i), std::end(i),
80	                           std::back_inserter(result));
81	  }
