65	void UriListParser::parseNext(std::vector<std::string>& uris, Option& op)
66	{
67	  const std::shared_ptr<OptionParser>& optparser = OptionParser::getInstance();
68	  while (1) {
69	    if (!line_.empty() && line_[0] != '#') {
70	      util::split(line_.begin(), line_.end(), std::back_inserter(uris), '\t',
71	                  true);
72	      // Read options
73	      std::stringstream ss;
74	      while (1) {
75	        line_ = fp_->getLine();
76	        if (line_.empty()) {
77	          if (fp_->eof()) {
78	            break;
79	          }
80	          else if (!*fp_) {
81	            throw DL_ABORT_EX("UriListParser:I/O error.");
82	          }
83	          else {
84	            continue;
85	          }
86	        }
87	        if (line_[0] == ' ' || line_[0] == '\t') {
88	          ss << line_ << "\n";
89	        }
90	        else if (line_[0] == '#') {
91	          continue;
92	        }
93	        else {
94	          break;
95	        }
96	      }
97	      optparser->parse(op, ss);
98	      return;
99	    }
100	    line_ = fp_->getLine();
101	    if (line_.empty()) {
102	      if (fp_->eof()) {
103	        return;
104	      }
105	      else if (!*fp_) {
106	        throw DL_ABORT_EX("UriListParser:I/O error.");
107	      }
108	    }
109	  }
110	}
111	
112	bool UriListParser::hasNext()
113	{
114	  bool rv = !line_.empty() || (fp_ && *fp_ && !fp_->eof());
115	  if (!rv) {
116	    fp_->close();
117	  }
118	  return rv;
119	}
