52	template <typename InputIterator>
53	InputIterator expandChoice(std::vector<std::string>& res, InputIterator first,
54	                           InputIterator last)
55	{
56	  ++first;
57	  InputIterator i = std::find(first, last, '}');
58	  if (i == last) {
59	    throw DL_ABORT_EX("Missing '}' in the parameterized string.");
60	  }
61	  std::vector<Scip> choices;
62	  util::splitIter(first, i, std::back_inserter(choices), ',', true, false);
63	  std::vector<std::string> res2;
64	  res2.reserve(res.size() * choices.size());
65	  for (std::vector<std::string>::const_iterator i = res.begin(),
66	                                                eoi = res.end();
67	       i != eoi; ++i) {
