79	template <typename InputIterator>
80	int32_t fromBase26(InputIterator first, InputIterator last, char zero)
81	{
82	  int32_t res = 0;
83	  for (; first != last; ++first) {
84	    res *= 26;
85	    res += *first - zero;
86	    if (res > static_cast<int32_t>(UINT16_MAX)) {
87	      throw DL_ABORT_EX("Loop range overflow.");
88	    }
89	  }
90	  return res;
91	}
92	
93	std::string toBase26(int32_t n, char zero, size_t width);
