95	template <typename InputIterator>
96	InputIterator expandLoop(std::vector<std::string>& res, InputIterator first,
97	                         InputIterator last)
98	{
99	  ++first;
100	  InputIterator i = std::find(first, last, ']');
101	  if (i == last) {
102	    throw DL_ABORT_EX("Missing ']' in the parameterized string.");
103	  }
104	  InputIterator colon = std::find(first, i, ':');
105	  uint32_t step;
106	  if (colon == i) {
107	    step = 1;
108	  }
109	  else {
110	    if (!util::parseUIntNoThrow(step, std::string(colon + 1, i))) {
111	      throw DL_ABORT_EX("A step count must be a positive number.");
112	    }
113	    if (step > UINT16_MAX) {
114	      throw DL_ABORT_EX("Loop step overflow.");
115	    }
116	  }
117	  InputIterator minus = std::find(first, colon, '-');
118	  if (minus == colon) {
119	    throw DL_ABORT_EX("Loop range missing.");
120	  }
121	  if (util::isNumber(first, minus) && util::isNumber(minus + 1, colon)) {
122	    uint32_t start, end;
123	    if (!util::parseUIntNoThrow(start, std::string(first, minus)) ||
124	        !util::parseUIntNoThrow(end, std::string(minus + 1, colon))) {
125	      throw DL_ABORT_EX("Loop range missing.");
126	    }
127	    if (start > UINT16_MAX || end > UINT16_MAX) {
128	      throw DL_ABORT_EX("Loop range overflow.");
129	    }
130	    if (start <= end) {
131	      std::string format;
132	      if (minus - first == colon - minus - 1) {
133	        format = fmt("%%0%lud", static_cast<unsigned long>(minus - first));
134	      }
135	      else {
136	        format = "%d";
137	      }
138	      std::vector<std::string> res2;
139	      res2.reserve(res.size() * ((end + 1 - start) / step));
140	      for (std::vector<std::string>::const_iterator i = res.begin(),
141	                                                    eoi = res.end();
142	           i != eoi; ++i) {
143	        for (uint32_t j = start; j <= end; j += step) {
144	          res2.push_back(*i);
145	          res2.back() += fmt(format.c_str(), j);
146	        }
147	      }
148	      res.swap(res2);
149	    }
150	  }
151	  else if ((util::isLowercase(first, minus) &&
152	            util::isLowercase(minus + 1, colon)) ||
153	           (util::isUppercase(first, minus) &&
154	            util::isUppercase(minus + 1, colon))) {
155	    char zero = ('a' <= *first && *first <= 'z' ? 'a' : 'A');
156	    int32_t start, end;
157	    start = fromBase26(first, minus, zero);
158	    end = fromBase26(minus + 1, colon, zero);
159	    if (start <= end) {
160	      size_t width;
161	      if (minus - first == colon - minus - 1) {
162	        width = minus - first;
163	      }
164	      else {
165	        width = 0;
166	      }
167	      std::vector<std::string> res2;
168	      res2.reserve(res.size() * ((end + 1 - start) / step));
169	      for (std::vector<std::string>::const_iterator i = res.begin(),
170	                                                    eoi = res.end();
171	           i != eoi; ++i) {
172	        for (int32_t j = start; j <= end; j += step) {
173	          res2.push_back(*i);
174	          res2.back() += toBase26(j, zero, width);
175	        }
176	      }
177	      res.swap(res2);
178	    }
179	  }
180	  else {
181	    throw DL_ABORT_EX("Invalid loop range.");
182	  }
183	  return i + 1;
184	}
