186	// Expand parameterized string.
187	// The available parameters are loop [] and choice {}.
188	//
189	// Loop: [START-END:STEP]
190	//
191	// A is arbitrary string. START and END must satisfy one of following
192	// condition:
193	//
194	// * both are decimal digits and START <= END.
195	//
196	// * both are composed of 'a' to 'z' letter and START <= END
197	//   lexicographically.
198	//
199	// * both are composed of 'A' to 'Z' letter and START <= END
200	//   lexicographically.
201	//
202	// Leading zeros in START and END are kep preserved if the length of
203	// START and END in string representation is equal.
204	//
205	// When loop through START to END, we include both START and END.
206	//
207	// STEP is decimal number and it is used as loop step.  STEP can be
208	// omitted. If omitted, preceding ':' also must be omitted.
209	//
210	// START, END and STEP must be less than or equal to 65535 in decimal.
211	//
212	// Examples:
213	// "alpha:[1-2]:bravo" -> ["alpha:1:bravo", "alpha:2:bravo"]
214	// "alpha:[05-10:5]" -> ["alpha:05:bravo", "alpha:10:bravo"]
215	//
216	// Choice: {C1,C2,...,Cn}
217	//
218	// C1 to Cn are arbitrary string but they cannot contain ','.
219	//
220	// Examples:
221	// "alpha:[foo,bar]:bravo" -> ["alpha:foo:bravo", "alpha:bar:bravo"]
222	template <typename InputIterator, typename OutputIterator>
223	void expand(InputIterator first, InputIterator last, OutputIterator out)
224	{
225	  std::vector<std::string> res;
226	  res.push_back("");
227	  while (first != last) {
228	    InputIterator i = first;
229	    for (; i != last && *i != '{' && *i != '['; ++i)
230	      ;
231	    for (auto& re : res) {
232	      re.append(first, i);
233	    }
234	    first = i;
235	    if (first == last) {
236	      break;
237	    }
238	    if (*first == '{') {
239	      first = expandChoice(res, first, last);
240	    }
241	    else if (*first == '[') {
242	      first = expandLoop(res, first, last);
243	    }
244	  }
245	  if (res.size() != 1 || !res[0].empty()) {
246	    std::copy(res.begin(), res.end(), out);
247	  }
248	}
